import json,base64,hashlib
from pathlib import Path
data=json.loads('{"rag/service/retrieval_server.py": "", "rag/service/web/index.html": "", "rag/service/web/style.css": "", "rag/service/web/app.js": "", "rag/eval/tests/test_web_ui.py": "", "rag/client/open_test_web.ps1": "", "rag/client/run_on_server.ps1": "", "docs/WEB_TEST_MVP.md": "", "rag/eval/reports/test_web_v1.json": "", "docs/PROJECT_MEMORY.md": "", "docs/PROJECT_STATUS_AND_ARCHITECTURE.md": ""}')
for n,b in data.items():
 p=Path(n);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
r=json.loads(Path('rag/eval/reports/test_web_v1.json').read_text())
for n,h in r['file_sha256'].items():assert hashlib.sha256(Path(n).read_bytes()).hexdigest()==h,n
print('Web MVP files and evidence hashes synchronized')
PY
